    static TreeNode build(List<String> tk) {
        if (tk.isEmpty() || tk.get(0).equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(tk.get(0)));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tk.size()) {
            TreeNode node = q.poll();
            if (i < tk.size() && !tk.get(i).equals("null")) {
                node.left = new TreeNode(Integer.parseInt(tk.get(i)));
                q.add(node.left);
            }
            i++;
            if (i < tk.size() && !tk.get(i).equals("null")) {
                node.right = new TreeNode(Integer.parseInt(tk.get(i)));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> tk = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tk.add(st.nextToken());
        }
        int[] res = minPerLevel(build(tk));
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "");
        System.out.println(sb);
    }
}

